// InvalidTransitionErrorResponse HTTP 409 response for invalid agent-state transitions (STATE-03, D-37).
// Extends the canonical error envelope with `from` and `to` — the
// requested state pair that is not in the allowed transition matrix.
type InvalidTransitionErrorResponse struct {
	Error InvalidTransitionErrorResponseError `json:"error"`

	// From Agent availability status values (STATE-01).
	//
	// **Agent-toggleable:**
	// - `Ready` — available to receive interactions
	// - `NotReady` — unavailable (no sub-reasons; contrast with Break)
	// - `Break` — temporary unavailability with a configurable reason
	//
	// **System-set:**
	// - `Engaged` — currently handling an interaction (system-initiated only)
	// - `WrapUp` — post-interaction after-contact work period (system-initiated)
	// - `Offline` — agent is logged out or timed out (system-initiated)
	From   AgentStatus `json:"from"`
	Reason string      `json:"reason"`

	// RequestId A UUIDv7 (RFC 9562 §5.7) time-ordered unique identifier.
	// Version must be 7 or higher; UUIDv4 and lower are rejected.
	// Example: `01901b2c-7f3a-7abc-8d4e-5f6a7b8c9d0e`
	RequestId *UUIDv7 `json:"request_id,omitempty"`

	// To Agent availability status values (STATE-01).
	//
	// **Agent-toggleable:**
	// - `Ready` — available to receive interactions
	// - `NotReady` — unavailable (no sub-reasons; contrast with Break)
	// - `Break` — temporary unavailability with a configurable reason
	//
	// **System-set:**
	// - `Engaged` — currently handling an interaction (system-initiated only)
	// - `WrapUp` — post-interaction after-contact work period (system-initiated)
	// - `Offline` — agent is logged out or timed out (system-initiated)
	To AgentStatus `json:"to"`
}

