// PatchAgentStatusRequest Request body for agent-state transitions (STATE-02, STATE-03, STATE-04,
// STATE-05). Single transition per call (OQ-3A resolution).
//
// **Allowed agent-initiated transitions** (STATE-02):
// - `NotReady` → `Ready`
// - `Ready` → `NotReady`
// - `Ready` → `Break` (requires `break_reason_id`)
// - `Break` → `Ready`
// - `Break` → `NotReady`
// - `WrapUp` → `Ready`
// - `WrapUp` → `NotReady`
//
// **System-only transitions** (cannot be triggered via this endpoint):
// - `Ready` → `Engaged` (requires `engaged_channel`)
// - `Engaged` → `WrapUp`
// - `WrapUp` → `Ready` / `WrapUp` → `NotReady` (via TTL goroutine)
// - `* → Offline`, `Offline → NotReady` (login/logout events)
//
// A transition not in the allowed matrix returns HTTP 409 with
// `InvalidTransitionErrorResponse` (STATE-03, D-37).
type PatchAgentStatusRequest struct {
	// BreakReasonId Required when `to == Break` (STATE-04). Must reference a `break_reason` belonging to the same org. Cross-org break reason IDs return HTTP 422 (not a not_found — the entity may exist, it's just unauthorized for this org).
	BreakReasonId *UUIDv7 `json:"break_reason_id,omitempty"`

	// Force Admin override (D-84). When `true`, bypasses the transition matrix (skips HTTP 409 `invalid_transition`). Cross-row probes still run: a missing or cross-org `break_reason_id` still returns HTTP 422 (D-84 Pitfall 3). v0.1 stub auth allows any caller to pass `force=true`; v1 AUTH phase restricts to `org_admin` role. Use sparingly — every `force=true` call emits a WARN-level audit log entry (`state.force.applied`).
	Force *bool `json:"force,omitempty"`

	// PostInteractionState May be set while `status == Engaged` (STATE-06). Specifies the target state when WrapUp expires. Ignored on other transitions.
	PostInteractionState *PostInteractionState `json:"post_interaction_state,omitempty"`

	// To Agent availability status values (STATE-01).
	//
	// **Agent-toggleable:**
	// - `Ready` — available to receive interactions
	// - `NotReady` — unavailable (no sub-reasons; contrast with Break)
	// - `Break` — temporary unavailability with a configurable reason
	//
	// **System-set:**
	// - `Engaged` — currently handling an interaction (system-initiated only)
	// - `WrapUp` — post-interaction after-contact work period (system-initiated)
	// - `Offline` — agent is logged out or timed out (system-initiated)
	To AgentStatus `json:"to"`
}

// PostInteractionState The state the agent transitions to after the WrapUp period ends (STATE-06). Set by the agent while Engaged. Applied by the system when WrapUp expires.
type PostInteractionState string

